const interpolate = (value, variables = {}) => value.replace(/\{(\w+)\}/g, (_, key) => variables[key] ?? `{${key}}`);
export const translate = (language, key, variables) => interpolate(messages[language]?.[key] ?? messages.en[key] ?? key, variables);

